import os
import numpy as np
import pandas as pd

from server.storage.accelerometer import AccelWriter

RCS_ACCEL_SF = 16   # ms
RUNE_WATCH_SF = 20   # ms


def make_blip_data(start, stop, sf, blip_start, blip_len):
    times = np.arange(start, stop, sf)
    data = np.zeros(times.shape)
    blip = np.logical_and(blip_start <= times, times < blip_start + blip_len)
    data[blip] = 1.0
    return times, data


def make_align_data(target, start_stagger=500, watch_err=300):

    base_start, base_end = -2211710400000, -2211710280000
    blip_time = base_start + 5000
    blip_len = 200

    srcs = []
    for i, side in enumerate(['left', 'right']):
        start = base_start + start_stagger * i
        end = base_end + start_stagger * i
        side_rcs_src = os.path.join(target, f'rcs_{side}_{start}_{end}')
        os.makedirs(side_rcs_src, exist_ok=True)
        srcs.append(side_rcs_src)

        print(f'{side} blip time: {blip_time}')

        # Build RCS Accel Data
        accel_times, accel_data = make_blip_data(start, end, RCS_ACCEL_SF, blip_time, blip_len)
        pd.DataFrame.from_dict({
            'timestamp': accel_times, 'accel_x': accel_data, 'accel_y': accel_data, 'accel_z': accel_data
        }).set_index('timestamp').to_csv(os.path.join(side_rcs_src, 'AccelTimeDomain.csv'))

        # Build Rune watch data
        accel_times, accel_data = make_blip_data(start, end, RUNE_WATCH_SF, blip_time+watch_err, blip_len)
        pd.DataFrame.from_dict({
            'timestamp': accel_times/1000, 'accel_x': accel_data, 'accel_y': accel_data, 'accel_z': accel_data
        }).set_index('timestamp').to_csv(os.path.join(side_rcs_src, 'RUNEWatchAccel.csv'))
    return srcs


def read_accel(directory, filename):
    return pd.read_csv(os.path.join(directory, filename), index_col='timestamp')


def prep_accel_writer(left_src, right_src):

    out = os.path.join(os.path.dirname(left_src), 'align_test.h5')
    try:
        os.remove(out)
    except FileNotFoundError:
        pass
    writer = AccelWriter(out)
    writer.left_chest = read_accel(left_src, 'AccelTimeDomain.csv')
    writer.right_chest = read_accel(right_src, 'AccelTimeDomain.csv')
    writer.watch_data = (
        read_accel(left_src, 'RUNEWatchAccel.csv'), read_accel(right_src, 'RUNEWatchAccel.csv')
    )
    writer.metadata = {}
    return writer


def manual_test_manual_align(working_dir):
    srcs = make_align_data(working_dir)
    writer = prep_accel_writer(*srcs)
    writer.load()
    writer.write()


if __name__ == "__main__":
    manual_test_manual_align(r'D:\NeurohubSystems\DataNet\temp-data\write_tests\debug\accel_alignment')